// ---- Always-200 Vapi envelope -----------------------------------------
function vapiResult(toolCallId, text) {
  return [{ json: { results: [{ toolCallId, result: text }] } }];
}

const ctx = $('Parse Tool Call').first().json;
const row = $input.first().json || {};

if (!ctx.phone10) {
  return vapiResult(ctx.toolCallId, 'No usable phone number on this call, so I have no record to check.');
}
if (row.error || (!('client' in row) && !('job' in row) && !('quote' in row))) {
  // DB unreachable — degrade gracefully, never block the call.
  return vapiResult(ctx.toolCallId, 'I could not reach our records just now. Treat this as a new caller and carry on.');
}

const client = row.client, job = row.job, quote = row.quote;
const parts = [];

if (client && client.blacklisted) {
  return vapiResult(ctx.toolCallId,
    'DO NOT BOOK. This number is flagged in our records' +
    (client.blacklist_reason ? ' (' + client.blacklist_reason + ')' : '') +
    '. Be polite, take a message only, and tell them Anthony will follow up personally.');
}

if (client) {
  parts.push('Existing client: ' + client.name + (client.address ? ', ' + client.address : '') + '.');
  parts.push(client.sms_consent ? 'Already opted in to texts.' : 'No text consent on file yet.');
} else {
  parts.push('No client record for this number.');
}

if (job) {
  let j = 'Last job: ' + job.service_type + ', ' + job.status;
  if (job.status === 'scheduled' && job.appointment_date) {
    j += ' for ' + job.appointment_date + (job.appointment_time ? ' at ' + String(job.appointment_time).slice(0,5) : '');
  }
  parts.push(j + '.');
}

if (quote) {
  parts.push('Open quote for ' + spellDollars(quote.total_price) + ', still pending.');
}

return vapiResult(ctx.toolCallId, parts.join(' '));
